// openBrowser installs a view built in selection mode and lays it out.
func (a *App) openBrowser(view command.ViewType, model tea.Model) tea.Cmd {
	a.views[view] = model
	a.selectionLent = view
	a.currentView = view
	return tea.Batch(model.Init(), a.requestResize())
