package theme

import (
	"os"
	"path/filepath"
	"strings"

	"github.com/mattn/go-runewidth"
)

// FoldHome replaces the home directory prefix with "~". A path outside home is
// returned unchanged.
func FoldHome(path string) string {
	home, err := os.UserHomeDir()
	if err != nil || home == "" || path == "" {
		return path
	}
	rel, err := filepath.Rel(home, path)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return path
	}
	if rel == "." {
		return "~"
	}
	return "~" + string(filepath.Separator) + rel
}

// ShortPath renders path in at most maxWidth terminal columns, for a form field
// or a header value (§3.95).
//
// The order of what gives way is the order of what matters least:
//
//  1. the home prefix, folded to "~" whether or not it is needed — the long
//     form says nothing the short one does not;
//  2. the intermediate segments, reduced to their first rune from the left, the
//     way fish prints its prompt — `~/projects/workspace-entire/anthnel/devdesk`
//     becomes `~/p/workspace-entire/…` then `~/p/w/a/devdesk`, stopping as soon
//     as it fits. A hidden segment keeps its dot (`.devdesk` → `.d`): an
//     initial alone would name a different directory;
//  3. only then the head, via TruncateTailWidth, when even the fully reduced
//     form is too wide.
//
// The last segment is never reduced: it is the name the field is about.
func ShortPath(path string, maxWidth int) string {
	folded := FoldHome(path)
	if maxWidth <= 0 || runewidth.StringWidth(folded) <= maxWidth {
		return folded
	}

	sep := string(filepath.Separator)
	segs := strings.Split(folded, sep)
	// segs[0] is "" for an absolute path, "~" under home, or a volume ("C:");
	// none of those is a segment to reduce, and the last one is the name.
	for i := 1; i < len(segs)-1; i++ {
		segs[i] = initial(segs[i])
		if short := strings.Join(segs, sep); runewidth.StringWidth(short) <= maxWidth {
			return short
		}
	}
	return TruncateTailWidth(strings.Join(segs, sep), maxWidth)
}

// initial reduces a path segment to its first rune, keeping a leading dot.
func initial(seg string) string {
	runes := []rune(seg)
	switch {
	case len(runes) <= 1:
		return seg
	case runes[0] == '.':
		return string(runes[:2])
	default:
		return string(runes[:1])
	}
}

package theme

import (
	"path/filepath"
	"testing"

	"github.com/mattn/go-runewidth"
)

func TestFoldHome(t *testing.T) {
	home := "/home/dev"
	t.Setenv("HOME", home)

	cases := map[string]string{
		home:                     "~",
		home + "/projects/x":     "~/projects/x",
		"/usr/local/bin/trivy":   "/usr/local/bin/trivy",
		"/home/developer/elsewhere": "/home/developer/elsewhere",
		"":                       "",
	}
	for in, want := range cases {
		if got := FoldHome(in); got != want {
			t.Errorf("FoldHome(%q) = %q, want %q", in, got, want)
		}
	}
}

func TestShortPathGivesWayInOrder(t *testing.T) {
	if filepath.Separator != '/' {
		t.Skip("cases are written with /")
	}
	t.Setenv("HOME", "/home/dev")
	long := "/home/dev/projects/workspace-entire/anthnel/devdesk"

	cases := []struct {
		name  string
		path  string
		width int
		want  string
	}{
		{"fits once folded", long, 60, "~/projects/workspace-entire/anthnel/devdesk"},
		{"first segment reduced", long, 38, "~/p/workspace-entire/anthnel/devdesk"},
		{"stops as soon as it fits", long, 26, "~/p/w/anthnel/devdesk"},
		{"every intermediate reduced", long, 15, "~/p/w/a/devdesk"},
		{"head truncated last", long, 12, "...a/devdesk"},
		{"hidden segment keeps its dot", "/home/dev/.config/devdesk/config.yaml", 25, "~/.c/devdesk/config.yaml"},
		{"outside home", "/usr/local/lib/trivy/bin/trivy", 20, "/u/l/l/t/b/trivy"},
		{"home itself", "/home/dev", 1, "~"},
		{"no budget means no shortening", long, 0, "~/projects/workspace-entire/anthnel/devdesk"},
		{"multibyte segments", "/home/dev/données/été/rapport.md", 16, "~/d/été/rapport.md"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got := ShortPath(c.path, c.width)
			if got != c.want {
				t.Errorf("ShortPath(%q, %d) = %q, want %q", c.path, c.width, got, c.want)
			}
			if c.width > 0 && runewidth.StringWidth(got) > c.width && got != "~" {
				t.Errorf("%q is wider than %d", got, c.width)
			}
		})
	}
}

