package filebrowser

import "github.com/anthnel/devdesk/internal/fsbrowse"

// ── Picker contract ─────────────────────────────────────────────────────────
//
// Any view may borrow this one to have a path chosen (§3.95). The borrower sends
// PickRequestMsg; the router lends a picker, and delivers PathPickedMsg or
// PickCancelledMsg back to the borrower. One pair for every borrower rather than
// a translation per borrower (compare internal/app/selection.go): the answer is
// always a path, and Tag is how a form with several path fields knows which one
// it is for.

// PickKind is what the picker lets the user choose.
type PickKind int

const (
	// PickDir picks a directory. The browsed directory itself is offered as
	// the first row ("."), so an empty directory can be picked too.
	PickDir PickKind = iota
	// PickFile picks a regular file.
	PickFile
)

// PickRequestMsg asks the router to open a picker. Start is the value the field
// currently holds — the picker opens there, or at its nearest existing ancestor.
type PickRequestMsg struct {
	Kind   PickKind
	Start  string
	Prompt string
	Tag    string
}

// PathPickedMsg carries the chosen absolute path back to the borrower.
type PathPickedMsg struct {
	Tag  string
	Path string
}

// PickCancelledMsg says the picker was closed without a choice.
type PickCancelledMsg struct {
	Tag string
}

// ── Internal messages ───────────────────────────────────────────────────────

// EntriesLoadedMsg carries a listing of Dir back into Update (Rule 110).
type EntriesLoadedMsg struct {
	Dir     string
	Entries []fsbrowse.Entry
}

// LoadErrorMsg says Dir could not be listed.
type LoadErrorMsg struct {
	Dir string
	Err error
}

// EntryCreatedMsg reports N.
type EntryCreatedMsg struct {
	Path string
	Err  error
}

// DeletePreparedMsg carries what the confirmation needs to say about an entry:
// how much a directory holds is read off the disk, so it is a Cmd's answer.
type DeletePreparedMsg struct {
	Entry fsbrowse.Entry
	Count int
}

// EntryDeletedMsg reports D. It is a jobs.Reporter (jobs.go).
type EntryDeletedMsg struct {
	Path string
	Err  error
}

// PathCopiedMsg reports Y.
type PathCopiedMsg struct {
	Path string
	Err  error
}

// Package filebrowser is the `:files` view (§3.95): a browser over the whole
// filesystem that creates and deletes entries, and — lent by the router — the
// picker a form's Browse button opens to choose a path.
//
// It is the workspaces view without the git: no enrichment walk, no scan
// columns, no root it cannot leave. What the two share is what a row is, which
// is internal/fsbrowse.
package filebrowser

import (
	"os"
	"path/filepath"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/fsbrowse"
	"github.com/anthnel/devdesk/internal/jobs"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
)

// mode is what holds the keyboard. A picker is not a mode: it is the same table
// with a different enter, so it is a field (pick) rather than a state here.
type mode int

const (
	modeNormal mode = iota
	modeCreating
	modeConfirmingDelete
)

// Model is the file browser.
type Model struct {
	config *config.Config
	mode   mode

	// currentPath is the directory listed; requested is the one a load is in
	// flight for. A listing is accepted only for requested — the stale-listing
	// guard ws has as listingPath — and currentPath moves only once it has
	// arrived, so a directory that cannot be read leaves the screen on the one
	// that could.
	currentPath string
	requested   string
	// pendingSelect is the path the cursor lands on once the listing arrives:
	// the directory just left on ←, the entry just created on N.
	pendingSelect string

	table   datatable.Model[row]
	footer  sharedcomponents.FooterMessage
	confirm *sharedcomponents.ConfirmModal
	pending *fsbrowse.Entry // what the confirmation is about
	form    *createForm

	// pick is non-nil when the view is lent as a picker.
	pick *PickRequestMsg

	jobs          []jobs.Run
	width, height int
}

// row is one line of the table. self marks the picker's "." row — the browsed
// directory itself, offered first so an empty directory can still be chosen.
type row struct {
	fsbrowse.Entry
	self bool
}

// New builds the `:files` view, opened on the home directory.
func New(cfg *config.Config) Model {
	return Model{
		config:      cfg,
		requested:   homeDir(),
		currentPath: "",
		table: datatable.New(datatable.Config[row]{
			Columns:    columns(),
			SortColumn: -1, // fsbrowse.List's order: directories first, then by name
		}),
	}
}

// NewPicker builds the view lent to a form: it opens where the field points,
// and enter chooses instead of opening.
func NewPicker(cfg *config.Config, req PickRequestMsg) Model {
	m := New(cfg)
	m.pick = &req
	start, selected := startOf(req)
	m.requested = start
	m.pendingSelect = selected
	return m
}

// startOf decides where a picker opens: the field's value when it is a
// directory, its parent with the cursor on it when it is a file, the nearest
// existing ancestor otherwise, and home when the field is empty.
func startOf(req PickRequestMsg) (dir, selected string) {
	near := fsbrowse.NearestExisting(req.Start)
	if near == "" {
		return homeDir(), ""
	}
	if info, err := os.Stat(near); err == nil && !info.IsDir() {
		return filepath.Dir(near), near
	}
	return near, ""
}

func homeDir() string {
	if home, err := os.UserHomeDir(); err == nil && home != "" {
		return home
	}
	return string(filepath.Separator)
}

// Init lists the starting directory.
func (m Model) Init() tea.Cmd {
	return m.load(m.requested)
}

// InEditMode tells the router a form, a modal or the filter holds the keyboard,
// and so does a picker: its esc answers the borrower, it does not leave.
func (m Model) InEditMode() bool {
	return m.mode != modeNormal || m.table.InEditMode() || m.pick != nil
}

// FilterBarVisible implements app.FilterBarView.
func (m Model) FilterBarVisible() bool {
	return m.mode == modeNormal && m.table.FilterBar().IsVisible()
}

// Picking reports whether this instance is lent as a picker — what the router
// asks before dropping it on `:files`.
func (m Model) Picking() bool { return m.pick != nil }

// CurrentPath is the directory listed, for tests and the router.
func (m Model) CurrentPath() string { return m.currentPath }

// load lists dir. Everything the closure needs is copied first (Rule 110).
func (m Model) load(dir string) tea.Cmd {
	showHidden := m.config.App.ShowHiddenFiles
	return func() tea.Msg {
		entries, err := fsbrowse.List(dir, showHidden)
		if err != nil {
			return LoadErrorMsg{Dir: dir, Err: err}
		}
		return EntriesLoadedMsg{Dir: dir, Entries: entries}
	}
}

// navigate asks for dir, selecting selected once it arrives.
func (m Model) navigate(dir, selected string) (tea.Model, tea.Cmd) {
	m.requested = dir
	m.pendingSelect = selected
	return m, m.load(dir)
}

func (m *Model) resize() {
	m.table.Resize(m.width, max(m.height-1, 1))
	if m.form != nil {
		m.form.setWidth(m.width)
	}
}

// setEntries replaces the listing. A picker for a directory gets its "." row.
func (m *Model) setEntries(entries []fsbrowse.Entry) {
	rows := make([]row, 0, len(entries)+1)
	if m.pick != nil && m.pick.Kind == PickDir {
		rows = append(rows, row{Entry: fsbrowse.Entry{Name: ".", Path: m.currentPath, IsDir: true}, self: true})
	}
	for _, e := range entries {
		rows = append(rows, row{Entry: e})
	}
	m.table.SetItems(rows)
	m.table.Remeasure()
}

// selected returns the row under the cursor.
func (m Model) selected() (row, bool) {
	return m.table.Selected()
}

// indexOf finds a path among the visible rows.
func (m Model) indexOf(path string) (int, bool) {
	for i, r := range m.table.Visible() {
		if !r.self && r.Path == path {
			return i, true
		}
	}
	return 0, false
}

package filebrowser

import (
	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/fsbrowse"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/fileicon"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

const (
	colNameMin      = 16
	colSizeFixed    = 10 // "1023.9 MiB"
	colModifiedFixed = 12 // "30 days ago"
)

func columns() []datatable.Column[row] {
	return []datatable.Column[row]{
		{
			// Rule 125: a glyph is a column, untitled, two cells, coloured by
			// role. Directory and file are the two roles because they are the
			// two sets of actions a row offers (→ versus enter).
			Title: "", Sizing: datatable.SizingFixed, MinWidth: datatable.IconColumnWidth,
			Cell:  func(r row) string { return rowIcon(r) },
			Style: func(r row) lipgloss.Style { return theme.IconStyle(rowIconRole(r)) },
		},
		{
			Title: "Name", Sizing: datatable.SizingContent, MinWidth: colNameMin, Flex: 1,
			Cell:   func(r row) string { return r.Name },
			Search: func(r row) string { return r.Name },
		},
		{
			// A directory's size is its inode, not what it holds: a dash says
			// "not a number worth reading" where 4.0 KiB would mislead.
			Title: "Size", Sizing: datatable.SizingFixed, Optional: true, MinWidth: colSizeFixed,
			Cell: func(r row) string {
				if r.IsDir {
					return "-"
				}
				return fsbrowse.HumanSize(r.Size)
			},
			Style: func(r row) lipgloss.Style {
				if r.IsDir {
					return theme.DimStyle
				}
				return lipgloss.NewStyle()
			},
		},
		{
			Title: "Modified", Sizing: datatable.SizingFixed, Optional: true, MinWidth: colModifiedFixed,
			Cell: func(r row) string {
				if r.self {
					return ""
				}
				return theme.TimeAgo(r.ModTime)
			},
		},
	}
}

func rowIcon(r row) string {
	if r.IsDir {
		return theme.IconDirectory
	}
	return fileicon.For(r.Name)
}

func rowIconRole(r row) theme.IconRole {
	if r.IsDir {
		return theme.IconRoleDirectory
	}
	return theme.IconRoleFile
}

package filebrowser

import (
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/fsbrowse"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
)

// What the selected row allows, computed once and read by both GetShortcuts (to
// grey) and the handlers (to refuse) — Rule 130, the pattern of
// internal/ui/workspaces/availability.go.
//
// N is absent for the reason it is absent there: it creates in the browsed
// directory and never acts on the selection, so it applies on every row.
type actionSet struct {
	Enter  shortcut.Availability // open a file / pick the row
	Right  shortcut.Availability // enter a directory
	Delete shortcut.Availability
	Copy   shortcut.Availability
}

// The reasons, written once so the header, the footer and the tests agree.
const (
	reasonNoRow        = "No entry selected"
	reasonNotADir      = "Not a directory"
	reasonADir         = "A directory — → enters it"
	reasonNotAFile     = "Not a file — pick a file"
	reasonSelfRow      = "This is the directory being browsed — ← to leave it first"
	reasonProtected    = "A filesystem root or the home directory is never deleted from here"
	reasonDeleting     = "Being deleted"
	reasonNotADirToPick = "Not a directory — pick a directory"
)

func (m Model) actions() actionSet {
	r, ok := m.selected()
	if !ok {
		none := shortcut.Unavailable(reasonNoRow)
		return actionSet{Enter: none, Right: none, Delete: none, Copy: none}
	}
	a := actionSet{Enter: m.enterState(r), Right: shortcut.Availability{}, Delete: shortcut.Availability{}}
	if !r.IsDir || r.self {
		a.Right = shortcut.Unavailable(reasonNotADir)
	}
	switch {
	case r.self:
		a.Delete = shortcut.Unavailable(reasonSelfRow)
	case fsbrowse.IsRoot(r.Path) || isHome(r.Path):
		a.Delete = shortcut.Unavailable(reasonProtected)
	case m.deleting(r.Path):
		a.Delete = shortcut.Unavailable(reasonDeleting)
	}
	return a
}

// enterState is what enter does to a row: in a picker it chooses a row of the
// requested kind; otherwise it opens a file, and a directory is →'s.
func (m Model) enterState(r row) shortcut.Availability {
	if m.pick != nil {
		switch {
		case m.pick.Kind == PickDir && !r.IsDir:
			return shortcut.Unavailable(reasonNotADirToPick)
		case m.pick.Kind == PickFile && r.IsDir:
			return shortcut.Unavailable(reasonNotAFile)
		}
		return shortcut.Availability{}
	}
	if r.IsDir {
		return shortcut.Unavailable(reasonADir)
	}
	return shortcut.Availability{}
}

// guard refuses a key the header shows greyed, and says why (Rule 128: a Warn).
func (m Model) guard(s shortcut.Availability, act func() (tea.Model, tea.Cmd)) (tea.Model, tea.Cmd) {
	if !s.Enabled() {
		return m, m.footer.Warn(s.Reason)
	}
	return act()
}

package filebrowser

import (
	"os"
	"path/filepath"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/jobs"
)

// A delete is work like the workspaces one: it goes through the registry, so a
// large tree spins in `:jobs` and a second D on it is refused while it runs.

func deleteRun(path string) jobs.Run {
	return jobs.NewRun(jobs.KindDelete, command.ViewFiles, "", filepath.Base(path), path)
}

// deleting reports whether path is being deleted, by this view or another.
func (m Model) deleting(path string) bool {
	for _, run := range jobs.Unfinished(m.jobs) {
		if run.Kind != jobs.KindDelete {
			continue
		}
		for _, item := range run.Items {
			if item.Target == path && !item.State.Terminal() {
				return true
			}
		}
	}
	return false
}

// handleJobsChanged takes the router's snapshot.
func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
	m.jobs = msg.Runs
	m.footer.SetSpinnerFrame(msg.RenderedFrame)
	return m, nil
}

// Transition applies a delete's outcome to the registry.
func (m EntryDeletedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindDelete, Target: m.Path, State: jobs.ItemDone}
	if m.Err != nil {
		t.State = jobs.ItemFailed
		t.Detail = "delete failed — check logs"
	}
	return t
}

var _ jobs.Reporter = EntryDeletedMsg{}

func isHome(path string) bool {
	home, err := os.UserHomeDir()
	return err == nil && filepath.Clean(path) == filepath.Clean(home)
}

