	// every question about HEAD fails on it. Gating on one of those questions is
	// what made a fresh repository report no untracked files — it has nothing
	// but untracked files.
	if _, err := run(repoPath, "", "rev-parse", "--git-dir"); err != nil {
		return status, err
	}

	status.Branch = branchOf(repoPath)

	if remote, err := RemoteURL(repoPath); err == nil {
		status.Remote = remote
	}

	if out, err := run(repoPath, "", "status", "--porcelain"); err == nil {
		status.Modified, status.Untracked = countPorcelain(out)
	}

	// A branch with no upstream makes rev-list fail rather than answer zero,
	// which is what distinguishes the two.
	if behind, ahead, err := divergence(repoPath); err == nil {
		status.HasUpstream = true
		status.Behind, status.Ahead = behind, ahead
	}

	status.LastTag = lastTagOf(repoPath)

	return status, nil
}

// branchOf names the checked-out branch, including one that has no commit yet.
//
// symbolic-ref answers for an unborn HEAD, which rev-parse does not; rev-parse
// answers for a detached HEAD, which symbolic-ref does not. Both are ordinary
// states of a working copy, so both are asked.
func branchOf(repoPath string) string {
	if out, err := run(repoPath, "", "symbolic-ref", "--short", "HEAD"); err == nil {
		return strings.TrimSpace(out)
	}
	if out, err := run(repoPath, "", "rev-parse", "--abbrev-ref", "HEAD"); err == nil {
		return strings.TrimSpace(out)
	}
	return ""
}

// lastTagOf names the nearest tag reachable from HEAD, or "" when the
// repository has none — that is the common case, not a failure, so the error
// `git describe` returns for it is discarded rather than propagated.

// hand are not this directory's, so there is nothing here to enter yet. `←` is
// deliberately not guarded — it reads the stack, not the table, and a listing
// it overtakes is dropped on arrival.
func (m Model) navigateIn() (tea.Model, tea.Cmd) {
	if m.listingPath != m.currentPath {
		return m, nil
	}

	entry, ok := m.selectedEntry()
	if !ok || !entry.IsDir {
		return m, nil
	}

	// Save cursor position before navigating down
	m.cursorStack = append(m.cursorStack, m.table.Cursor())
	// Push current path onto navigation stack
	if m.currentPath != "" {
		m.navigationStack = append(m.navigationStack, m.currentPath)
	}
	m.currentPath = entry.Path
	m.activeTabIndex = m.tabCount() - 1
	m.pendingCursor = -1
	return m, m.loadEntries()
}

// navigateUp goes to the parent directory
func (m Model) navigateUp() (tea.Model, tea.Cmd) {
	if m.currentPath == "" {
		return m, nil
	}

	if len(m.navigationStack) > 0 {
		// Pop from stack
		m.currentPath = m.navigationStack[len(m.navigationStack)-1]
		m.navigationStack = m.navigationStack[:len(m.navigationStack)-1]
	} else {
		// Go back to root
		m.currentPath = ""
	}

	// Restore cursor position at the parent level after entries load
	if len(m.cursorStack) > 0 {
		m.pendingCursor = m.cursorStack[len(m.cursorStack)-1]
		m.cursorStack = m.cursorStack[:len(m.cursorStack)-1]
	} else {
		m.pendingCursor = -1
	}

	m.activeTabIndex = m.tabCount() - 1
	return m, m.loadEntries()
}
